@import url('https://fonts.googleapis.com/css2?family=Coming+Soon&display=swap');

/* === 1. FONT TOKENS === */
:root,
body {
  /* Google Calendar & Tasks Material 3 (GM3) Font Overrides */
  --gm3-ref-typeface-brand: 'Coming Soon', cursive !important;
  --gm3-ref-typeface-plain: 'Coming Soon', cursive !important;
}

/* === 2. FORCE COMING SOON (BOLD) EVERYWHERE EXCEPT ICONS === */
*:not(.google-material-icons):not(.material-icons):not(.material-icons-extended):not(.material-symbols-outlined):not(.DPvwYc) {
  font-family: 'Coming Soon', cursive !important;
  font-weight: 700 !important;
  font-synthesis: weight !important;
  letter-spacing: 0.2px;
}

/* Protect Google's icon fonts */
.google-material-icons,
.material-icons,
.material-icons-extended,
.material-symbols-outlined,
.DPvwYc {
  font-family: 'Google Material Icons', 'Material Icons Extended', 'Material Icons', 'Material Symbols Outlined' !important;
  font-weight: 400 !important;
}
